import { useEffect, useState } from "react";
import { collection, getDocs, addDoc, deleteDoc, doc } from "firebase/firestore";
import { db } from "../services/firebaseConfig";

export default function Transactions() {
  const [transactions, setTransactions] = useState([]);
  const [newTransaction, setNewTransaction] = useState({
    type: "Saída",
    category: "",
    value: "",
    date: "",
  });

  // Função pra buscar transações
  const fetchData = async () => {
    try {
      const querySnapshot = await getDocs(collection(db, "transactions"));
      const data = querySnapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
      setTransactions(data);
    } catch (err) {
      console.error("Erro ao buscar transações:", err);
      alert("Erro ao buscar transações. Cheque suas configs do Firebase.");
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Função pra adicionar nova transação
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!newTransaction.category || !newTransaction.value || !newTransaction.date) {
      alert("Preencha todos os campos!");
      return;
    }

    try {
      const docRef = await addDoc(collection(db, "transactions"), {
        ...newTransaction,
        value: parseFloat(newTransaction.value),
      });
      console.log("Transação adicionada com ID:", docRef.id);
      alert("✅ Transação adicionada com sucesso!");

      setNewTransaction({ type: "Saída", category: "", value: "", date: "" });
      fetchData();
    } catch (err) {
      console.error("Erro ao adicionar transação:", err);
      alert("❌ Erro ao adicionar transação. Cheque o console.");
    }
  };

  return (
    <div style={{ padding: "2rem" }}>
      <h1>Transações</h1>

      {/* FORMULÁRIO */}
      <form
        onSubmit={handleSubmit}
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "10px",
          maxWidth: "400px",
          marginTop: "1rem",
          background: "#151c2e",
          padding: "1rem",
          borderRadius: "12px",
        }}
      >
        <select
          value={newTransaction.type}
          onChange={(e) =>
            setNewTransaction({ ...newTransaction, type: e.target.value })
          }
        >
          <option value="Entrada">Entrada</option>
          <option value="Saída">Saída</option>
        </select>

        <input
          type="text"
          placeholder="Categoria (ex: Combustível)"
          value={newTransaction.category}
          onChange={(e) =>
            setNewTransaction({ ...newTransaction, category: e.target.value })
          }
        />

        <input
          type="number"
          placeholder="Valor"
          value={newTransaction.value}
          onChange={(e) =>
            setNewTransaction({ ...newTransaction, value: e.target.value })
          }
        />

        <input
          type="date"
          value={newTransaction.date}
          onChange={(e) =>
            setNewTransaction({ ...newTransaction, date: e.target.value })
          }
        />

        <button
          type="submit"
          style={{
            padding: "0.6rem",
            background: "#00c98d",
            color: "#fff",
            border: "none",
            borderRadius: "8px",
            fontWeight: "600",
            cursor: "pointer",
          }}
        >
          Adicionar
        </button>
      </form>

      {/* LISTAGEM */}
      <ul style={{ marginTop: "2rem", listStyle: "none", padding: 0 }}>
        {transactions.length === 0 ? (
          <p>Nenhuma transação encontrada.</p>
        ) : (
          transactions.map((t) => (
            <li
              key={t.id}
              style={{
                background: "#101522",
                padding: "10px",
                borderRadius: "8px",
                marginBottom: "8px",
              }}
            >
              <strong>{t.type}</strong> — {t.category} — R$ {t.value}
              <br />
              <small>{t.date}</small>
            </li>
          ))
        )}
      </ul>
    </div>
  );
}
